// PublicadorEventoPedido.cs — le a resposta de PutRecords antes de dar por certo

using Amazon.Kinesis;
using Amazon.Kinesis.Model;

public sealed class PublicadorEventoPedido
{
    private readonly IAmazonKinesis _kinesis;
    private readonly string _stream;
    private readonly ILogger<PublicadorEventoPedido> _log;

    public PublicadorEventoPedido(IAmazonKinesis kinesis, string stream,
        ILogger<PublicadorEventoPedido> log)
    {
        _kinesis = kinesis;
        _stream = stream;
        _log = log;
    }

    // A CHAVE e o id do pedido — nao o tipo do evento. E a linha que resolve
    // os dois sintomas do laboratorio: distribui a escrita (cardinalidade
    // alta) e garante que os eventos de UM pedido caiam no MESMO shard
    // (ordem). Trocar esta linha de volta para "evento.Tipo" reintroduz os
    // dois problemas ao mesmo tempo, porque tem a MESMA causa.
    private static string ChaveDeParticao(EventoPedido evento) => evento.IdPedido.ToString();

    public async Task PublicarLoteAsync(IReadOnlyList<EventoPedido> eventos,
        CancellationToken ct = default)
    {
        var pendentes = eventos
            .Select(e => new PutRecordsRequestEntry
            {
                PartitionKey = ChaveDeParticao(e),
                Data = new MemoryStream(JsonSerializer.SerializeToUtf8Bytes(e)),
            })
            .ToList();

        // Ate 4 tentativas: a primeira e as chamadas originais, as demais so
        // reenviam quem falhou. Backoff exponencial com jitter evita que o
        // proprio retry sincronizado piore o throttling que o causou.
        for (var tentativa = 1; tentativa <= 4 && pendentes.Count > 0; tentativa++)
        {
            var resposta = await _kinesis.PutRecordsAsync(new PutRecordsRequest
            {
                StreamName = _stream,
                Records = pendentes,
            }, ct);

            // O PONTO CENTRAL do laboratorio: a chamada acima NAO lanca
            // excecao por falha parcial. HTTP 200 e devolvido mesmo com
            // FailedRecordCount > 0 — quem so confere o status conclui
            // sucesso com registros que nunca entraram no stream.
            if (resposta.FailedRecordCount == 0)
                return;

            var proximaRodada = new List<PutRecordsRequestEntry>();
            for (var i = 0; i < resposta.Records.Count; i++)
            {
                var item = resposta.Records[i];
                if (item.ErrorCode is null) continue; // este teve sucesso

                _log.LogWarning(
                    "registro {Indice} falhou na tentativa {Tentativa}: {Codigo} — {Mensagem}",
                    i, tentativa, item.ErrorCode, item.ErrorMessage);
                proximaRodada.Add(pendentes[i]);
            }

            pendentes = proximaRodada;
            if (pendentes.Count > 0)
                await Task.Delay(BackoffComJitter(tentativa), ct);
        }

        if (pendentes.Count > 0)
        {
            // Esgotadas as tentativas do PRODUTOR — nao do stream. Isto e
            // perda real e precisa ser tratado como incidente, nunca como
            // log silencioso: metrica customizada + alarme, nao so LogError.
            _log.LogError(
                "{Quantidade} eventos descartados apos {Tentativas} tentativas — dado perdido",
                pendentes.Count, 4);
            throw new EventosPedidoNaoPublicadosException(pendentes.Count);
        }
    }

    private static TimeSpan BackoffComJitter(int tentativa)
    {
        var baseMs = Math.Pow(2, tentativa) * 100;
        var jitter = Random.Shared.Next(0, 100);
        return TimeSpan.FromMilliseconds(baseMs + jitter);
    }
}

public sealed record EventoPedido(Guid IdPedido, string Tipo, DateTimeOffset Instante, decimal Valor);

public sealed class EventosPedidoNaoPublicadosException(int quantidade)
    : Exception($"{quantidade} eventos de pedido nao foram publicados apos esgotar as tentativas");

# consumidor.tf — a Lambda em tempo real, o destino de falha, os alarmes

resource "aws_sqs_queue" "eventos_pedido_dlq" {
  name = "${var.projeto}-eventos-pedido-dlq"

  # 14 dias: maior que a retencao do stream, para dar tempo de investigar um
  # lote que falhou sem que a fila em si vire novo ponto de perda.
  message_retention_seconds = 1209600
  kms_master_key_id         = aws_kms_key.eventos.key_id
}

resource "aws_lambda_function" "alerta_fraude" {
  function_name = "${var.projeto}-alerta-fraude"
  role          = aws_iam_role.lambda_alerta_fraude.arn
  handler       = "FraudeFunction::FraudeFunction.Function::FunctionHandler"
  runtime       = "dotnet8"
  timeout       = 30
  memory_size   = 256

  environment {
    variables = {
      SNS_TOPIC_ARN = aws_sns_topic.alerta_risco.arn
    }
  }
}

resource "aws_lambda_event_source_mapping" "eventos_pedido_tempo_real" {
  event_source_arn  = aws_kinesis_stream.eventos_pedido.arn
  function_name     = aws_lambda_function.alerta_fraude.arn
  starting_position = "LATEST" # so o consumo normal comeca do fim; o replay usa outro mapping

  batch_size                        = 100
  maximum_batching_window_in_seconds = 2

  # Ate 10 lotes concorrentes POR SHARD. O Lambda continua garantindo ordem
  # por CHAVE de particao mesmo com paralelizacao > 1 — a concorrencia e
  # entre chaves diferentes do mesmo shard, nao dentro da mesma chave.
  parallelization_factor = 2

  # Um erro no lote e re-tentado ate 3 vezes, bissectando o lote pela metade
  # a cada tentativa — isola o registro ruim em vez de re-tentar o lote
  # inteiro do mesmo jeito repetidamente.
  bisect_batch_on_function_error = true
  maximum_retry_attempts         = 3
  maximum_record_age_in_seconds  = 3600

  destination_config {
    on_failure {
      # Esgotadas as tentativas, o lote vai para ca — e o shard SEGUE lendo
      # os proximos registros. Sem isto, um registro ruim travaria o shard
      # inteiro, e essa e a diferenca entre "um pedido com problema" e
      # "todo o stream parado".
      destination_arn = aws_sqs_queue.eventos_pedido_dlq.arn
    }
  }
}

resource "aws_sns_topic" "alerta_risco" {
  name              = "${var.projeto}-alerta-risco"
  kms_master_key_id = aws_kms_key.eventos.key_id
}

data "aws_iam_policy_document" "lambda_le_stream" {
  statement {
    effect = "Allow"
    actions = [
      "kinesis:GetRecords",
      "kinesis:GetShardIterator",
      "kinesis:DescribeStreamSummary",
      "kinesis:ListShards",
    ]
    resources = [aws_kinesis_stream.eventos_pedido.arn]
  }
  statement {
    effect    = "Allow"
    actions   = ["kms:Decrypt"]
    resources = [aws_kms_key.eventos.arn]
  }
  statement {
    effect    = "Allow"
    actions   = ["sqs:SendMessage"]
    resources = [aws_sqs_queue.eventos_pedido_dlq.arn]
  }
  statement {
    effect    = "Allow"
    actions   = ["sns:Publish"]
    resources = [aws_sns_topic.alerta_risco.arn]
  }
}

resource "aws_iam_role_policy" "lambda_le_stream" {
  name   = "${var.projeto}-lambda-le-stream"
  role   = aws_iam_role.lambda_alerta_fraude.id
  policy = data.aws_iam_policy_document.lambda_le_stream.json
}

# Os dois alarmes que decidem se o consumidor acompanha o pico, e nao a
# capacidade de escrita — que ja tem os seus proprios (nao mostrados aqui,
# ja cobertos pelo shard_level_metrics do kinesis.tf).
resource "aws_cloudwatch_metric_alarm" "iterator_age" {
  alarm_name          = "${var.projeto}-iterator-age-alta"
  namespace           = "AWS/Lambda"
  metric_name         = "IteratorAge"
  statistic           = "Maximum"
  period              = 60
  evaluation_periods  = 3
  # 30s de atraso e tolerado; acima disso o consumidor esta perdendo o pico,
  # nao so processando devagar.
  threshold           = 30000
  comparison_operator = "GreaterThanThreshold"
  treat_missing_data  = "notBreaching"

  dimensions = {
    FunctionName = aws_lambda_function.alerta_fraude.function_name
  }
  alarm_actions = [aws_sns_topic.alerta_operacao.arn]
}

resource "aws_cloudwatch_metric_alarm" "throughput_excedido" {
  alarm_name          = "${var.projeto}-shard-throughput-excedido"
  namespace           = "AWS/Kinesis"
  metric_name         = "WriteProvisionedThroughputExceeded"
  statistic           = "Sum"
  period              = 60
  evaluation_periods  = 2
  threshold           = 0
  comparison_operator = "GreaterThanThreshold"
  treat_missing_data  = "notBreaching"

  dimensions = {
    StreamName = aws_kinesis_stream.eventos_pedido.name
  }
  alarm_actions = [aws_sns_topic.alerta_operacao.arn]
}

// FraudeFunction.cs — le em ordem por pedido, e admite o limite do que sabe

using Amazon.Lambda.Core;
using Amazon.Lambda.KinesisEvents;
using Amazon.SimpleNotificationService;

namespace FraudeFunction;

public class Function
{
    private readonly IAmazonSimpleNotificationService _sns;
    private readonly string _topicoArn = Environment.GetEnvironmentVariable("SNS_TOPIC_ARN")!;

    // Cache em memoria, valido so ENQUANTO a execucao ficar quente. Nao e um
    // substituto para estado persistido: se o ambiente reciclar entre dois
    // eventos do mesmo pedido, o ultimo estado visto se perde. Para producao
    // de verdade isso pede uma tabela (DynamoDB), e essa decisao fica FORA
    // do escopo deste laboratorio, que e sobre ordem de ENTREGA, nao sobre
    // onde guardar estado de negocio — misturar os dois esconderia qual dos
    // dois esta sendo provado.
    private static readonly Dictionary<Guid, string> UltimoEventoVisto = new();

    public Function(IAmazonSimpleNotificationService sns) => _sns = sns;

    public async Task FunctionHandler(KinesisEvent evento, ILambdaContext contexto)
    {
        // Os registros deste lote pertencem TODOS ao mesmo shard, e chegam
        // na ordem em que o shard os recebeu — e ela so é confiável porque
        // a chave de particao é o id do pedido: todo evento de um pedido
        // sempre cai neste MESMO shard.
        foreach (var registro in evento.Records)
        {
            var dado = JsonSerializer.Deserialize<EventoPedidoLido>(
                registro.Kinesis.Data);
            if (dado is null) continue;

            if (UltimoEventoVisto.TryGetValue(dado.IdPedido, out var anterior)
                && anterior == "pedido_cancelado" && dado.Tipo == "pedido_pago")
            {
                // Deveria ser logicamente impossivel com a ordem preservada:
                // pago depois de cancelado. Se isto disparar, o problema nao
                // e o consumidor — e a garantia de shard sendo violada em
                // algum ponto anterior (ex.: reprocesso escrevendo no
                // caminho de tempo real por engano).
                contexto.Logger.LogWarning(
                    $"ordem suspeita no pedido {dado.IdPedido}: pago apos cancelado");
            }

            if (anterior == "pedido_pago" && dado.Tipo == "pedido_cancelado")
            {
                await _sns.PublishAsync(_topicoArn,
                    $"pedido {dado.IdPedido}: cancelado {SegundosDesde(anterior)}s apos o pagamento — revisar estorno");
            }

            UltimoEventoVisto[dado.IdPedido] = dado.Tipo;
        }
    }

    private static long SegundosDesde(string _) => 0; // ilustrativo: o calculo real usa o instante do evento anterior
}

public sealed record EventoPedidoLido(Guid IdPedido, string Tipo, DateTimeOffset Instante, decimal Valor);
